// Página de Produção Diária — camada ui/ da feature producao (FSD)
// Portada de src/pages/ProducaoDiaria.tsx
import { useState, useEffect } from "react";
import { Sun, Moon, Leaf, LogOut } from "lucide-react";
import { usePermissions } from "@/shared/hooks/usePermissions";
import { PermissionBlur } from "@/shared/ui/PermissionBlur";
import { DailyProductionForm } from "@/components/forms/DailyProductionForm";
import { FormErrorBoundary } from "@/shared/ui/FormErrorBoundary";
import { Button } from "@/shared/ui/button";
import { useTheme } from "next-themes";
import { useAuth } from "@/shared/hooks/useAuth";
import { StoreSelector } from "@/shared/ui/DashboardStoreSelector";
import { Avatar, AvatarFallback } from "@/shared/ui/avatar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import { toast } from "@/shared/hooks/use-toast";
import { wideError } from '@/shared/lib/telemetry/wide-events';
import { useMiaPageContext } from '@/features/mia/hooks/useMiaPageContext';
import { ProducaoDiariaReportButton, PadronizarNomesProducaoButton } from '@/features/producao';

export default function ProducaoDiariaPage() {
  useMiaPageContext({
    description: 'Produção diária do Momma (doces saudáveis, validade 3-5 dias) — lançar produção do dia por produto e loja, fechar produção, ver histórico.',
    natural_language_hints: '"produção hoje" = lançamento do dia atual; "ontem" = histórico; "fechar produção" = consolidar. Shelf-life curto (3-5d) é cap obrigatório.',
    capabilities: ['lancar_producao', 'consultar_historico', 'fechar_dia'],
    primary_entity: 'daily_production',
  });
  const { canViewEstoque, hasPermission } = usePermissions();
  const { theme, setTheme } = useTheme();
  const { userProfile, user, signOut } = useAuth();
  const [serverVersion, setServerVersion] = useState<string | null>(null);

  useEffect(() => {
    fetch(`/version.json?t=${Date.now()}`)
      .then(res => res.json())
      .then(data => setServerVersion(data.version))
      .catch(err => wideError('producao_diaria.version_fetch_failed', 'Falha ao buscar versão do servidor', { attributes: { 'error.message': String(err), 'operation.name': 'fetchServerVersion' } }));
  }, []);

  const hasAccess = hasPermission('view_producao') || canViewEstoque();

  return (
    <PermissionBlur
      hasPermission={hasAccess}
      moduleName="Estoque"
      permissionName="view_producao"
    >
      <div className="min-h-screen w-full bg-white dark:bg-[#0A0A0A] font-sans relative overflow-x-hidden transition-colors duration-300">
        {/* Store Awning Stripe Effect (Top Border) */}
        <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50 shadow-sm" />

        {/* Animated Plant Background Elements */}
        <div
          className="fixed top-[-5%] right-[-10%] md:right-[-5%] w-[300px] md:w-[500px] h-[300px] md:h-[500px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse"
          style={{ animationDuration: '10s' }}
        >
          <Leaf className="w-full h-full text-[#57715B] rotate-12" />
        </div>
        <div
          className="fixed bottom-[-10%] left-[-15%] md:left-[-5%] w-[400px] md:w-[600px] h-[400px] md:h-[600px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse delay-1000"
          style={{ animationDuration: '12s' }}
        >
          <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
        </div>

        {/* Soft Ambient Glows */}
        <div className="fixed top-[20%] left-[10%] w-[200px] md:w-[400px] h-[200px] md:h-[400px] bg-[#57715B]/5 rounded-full blur-[80px] pointer-events-none" />
        <div className="fixed bottom-[30%] right-[10%] w-[250px] md:w-[500px] h-[250px] md:h-[500px] bg-[#C5A065]/5 rounded-full blur-[80px] pointer-events-none" />

        <div className="relative z-10 w-full max-w-[1600px] mx-auto space-y-4 px-4 sm:px-6 py-6 animate-in fade-in duration-500">
          {/* Header */}
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 pb-2">
            <div className="space-y-1">
              <div className="flex items-center gap-3">
                <div className="hidden md:flex h-12 w-12 rounded-2xl bg-[#57715B]/10 dark:bg-[#E6DCCF]/10 items-center justify-center">
                  <Leaf className="h-6 w-6 text-[#57715B] dark:text-[#E6DCCF]" />
                </div>
                <div>
                  <h1 className="text-4xl md:text-5xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF] font-serif mb-1 drop-shadow-sm">
                    Produção Diária
                  </h1>
                  <p className="text-xs md:text-sm text-[#8C7B6D] dark:text-[#9BA59C] font-medium tracking-widest uppercase opacity-80 pl-1">
                    Gerencie a produção e registre entradas
                  </p>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-2 md:gap-4">
              {/* PDF Report */}
              <ProducaoDiariaReportButton />
              {/* TEMP: Padronização de nomes — remover após uso (jun/2026) */}
              <PadronizarNomesProducaoButton />

              {/* Store Selector */}
              <div className="hidden md:block">
                <StoreSelector />
              </div>
              <div className="md:hidden">
                <StoreSelector />
              </div>

              {/* Theme Toggle */}
              <Button
                variant="ghost"
                size="icon"
                onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
                className="h-10 w-10 rounded-full bg-[#E6DCCF]/40 dark:bg-white/10 border border-[#57715B]/10 dark:border-white/5 hover:bg-[#57715B]/10 transition-all hover:scale-105"
              >
                <Sun className="h-5 w-5 text-[#57715B] dark:text-[#8FA893] rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
                <Moon className="absolute h-5 w-5 text-[#8FA893] rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
              </Button>

              {/* Profile Menu */}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="ghost"
                    className="h-10 w-10 rounded-full p-0 hover:bg-transparent relative hover:scale-105 transition-transform"
                  >
                    <Avatar className="h-10 w-10 ring-2 ring-[#E6DCCF] dark:ring-zinc-700 shadow-md">
                      <AvatarFallback className="bg-[#E6DCCF] text-[#57715B] font-bold text-sm border border-[#C5A065]/20">
                        {(user?.user_metadata?.nome || 'U')
                          .slice(0, 2)
                          .toUpperCase()}

